style.css:
@-moz-document domain("youtube.com") {
/* GLOBAL COLORS */
:root {
  --aero-blue: #c7f0ff;
  --aero-light: #e9fbff;
  --aero-border: #83dafa;
  --aero-light: #08783c;
  --aero-mint: #39c879;
}

/* BACKGROUND - AERO SKY, WATER AND HILLS */
html, body, ytd-app {
  background-color: #a9eaff !important;
  color: var(--aero-green) !important;
}

ytd-app {
  background-image:
    radial-gradient(circle at 12% 20%, #ffffffbb 0 3px, transparent 5px),
    radial-gradient(circle at 75% 30%, #ffffff99 0 7px, transparent 10px),
    radial-gradient(circle at 88% 65%, #ffffffaa 0 5px, transparent 8px),
    radial-gradient(ellipse at 50% 105%, #38c9ad 0%, #78e0bd 18%, transparent 48%),
    radial-gradient(ellipse at 15% 100%, #6acb78 0%, transparent 40%),
    linear-gradient(180deg, #39baff 0%, #a9eaff 48%, #d7fbff 72%, #71d9e9 100%) !important;
  background-attachment: fixed !important;
}

/* SIDEBAR */
#guide-content,
ytd-guide-renderer,
ytd-mini-guide-renderer {
  background: linear-gradient(
    135deg,
    #e8fbff 0%,
    #bceeff 45%,
    #8bdaf5 100%
  ) !important;

  border-right: 1px solid var(--aero-border) !important;
  box-shadow:
    inset -3px 0 10px #ffffff88,
    3px 0 15px #39bde955 !important;
}

/* SIDEBAR ITEMS */
ytd-guide-entry-renderer #endpoint,
ytd-guide-entry-renderer yt-formatted-string {
  color: var(--aero-green) !important;
}

ytd-guide-entry-renderer:hover #endpoint {
  background: linear-gradient(#ffffff, #a9eaff) !important;
  border-radius: 14px !important;
}

/* HEADER */
ytd-masthead {
  background: linear-gradient(
    180deg,
    #394E1B,
    #c4f1ffdd
  ) !important;

  box-shadow: 0 4px 15px #39bde944 !important;
}

/* SEARCH */
#container.ytd-searchbox {
  background: linear-gradient(#ffffff, #c5f3ff, #a4e5fa) !important;
  border: 1px solid #70cfee !important;
  border-radius: 30px !important;
  box-shadow: inset 0 2px 5px white, 0 3px 10px #42bce955 !important;
}

#search-input input {
  color: var(--aero-green) !important;
}

/* EMERALD TEXT */
#video-title,
#channel-name,
#owner-name,
#text,
#description,
h1, h2, h3,
yt-formatted-string,
.yt-core-attributed-string {
  color: var(--aero-green) !important;
}

/* VIDEO CARDS */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-compact-video-renderer {
  border-radius: 18px !important;
}

/* THUMBNAILS */
ytd-thumbnail {
  border-radius: 18px !important;
  overflow: hidden !important;
  border: 2px solid #b9efff !important;
  box-shadow: 0 4px 15px #24aee966 !important;
  transition: .25s ease !important;
}

ytd-thumbnail:hover {
  transform: translateY(-3px) scale(1.02) !important;
  box-shadow: 0 8px 22px #27c1ed99 !important;
}

/* CATEGORY CHIPS */
yt-chip-cloud-chip-renderer {
  background: linear-gradient(
    180deg,
    #ffffff,
    #d4f7ff,
    #9ce3f8
  ) !important;

  border: 1px solid #8adcf5 !important;
  border-radius: 25px !important;
  box-shadow: inset 0 2px 4px white,
              0 3px 8px #35bce955 !important;
}

/* BUTTONS */
yt-button-shape-next button {
  background: linear-gradient(
    180deg,
    #ffffff,
    #c8f2ff,
    #85d9f5
  ) !important;

  border: 1px solid #8adcf5 !important;
  border-radius: 25px !important;
  box-shadow: inset 0 2px 4px white,
              0 3px 8px #35bce955 !important;
}

/* SUBSCRIBE BUTTON */
yt-button-shape-next button[aria-label*="Subscribe"] {
  background: linear-gradient(
    180deg,
    #aaffc8,
    #39d887,
    #139b57
  ) !important;
  color: limegreen !important;
}

/* VIDEO PLAYER */
.html5-video-player {
  border-radius: 18px !important;
  overflow: hidden !important;
  border: 2px solid #a5eaff !important;
  box-shadow: 0 5px 20px #36b9ed66 !important;
}

/* SHORTS */
ytd-reel-item-renderer {
  border-radius: 18px !important;
  overflow: hidden !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
  width: 11px;
}

::-webkit-scrollbar-track {
  background: #d5f5ff;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(
    #eaffff,
    #78dafa,
    #28b4e2
  );
  border-radius: 20px;
  border: 2px solid #d5f5ff;
}

/* TEXT SELECTION */
::selection {
  background: #39d887 !important;
  color: yellowgreen !important;
}
}
